import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame, // added
} from './neon.js';

// ... (existing tests)

const mockCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('brick collision: top face bounce', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 50, r: 7, vx: 0, vy: 100 }; // moving DOWN
  state.bricks = [
    { x: 80, y: 55, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vy < 0, 'vy should flip to UP after hitting top face');
});

test('brick collision: bottom face bounce', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 80, r: 7, vx: 0, vy: -100 }; // moving UP
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vy > 0, 'vy should flip to DOWN after hitting bottom face');
});

test('brick collision: left face bounce', () => {
  const state = createState(1);
  state.ball = { x: 75, y: 70, r: 7, vx: 100, vy: 0 }; // moving RIGHT
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT after hitting left face');
});

test('brick collision: right face bounce', () => {
  const state = createState(1);
  state.ball = { x: 125, y: 70, r: 7, vx: -100, vy: 0 }; // moving LEFT
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vx > 0, 'vx should flip to RIGHT after hitting right face');
});

test('brick collision: corner bounce', () => {
  const state = createState(1);
  state.ball = { x: 75, y: 55, r: 7, vx: 100, vy: 100 }; // moving DOWN-RIGHT
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both vx and vy should flip after corner hit');
});

test('brick collision: push out', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 60, r: 7, vx: 0, vy: 100 }; // deeply overlapping
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(!collides(state.ball, state.bricks[0]), 'ball should be pushed out of the brick');
});

test('brick collision: neighbours (single bounce)', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 60, r: 7, vx: 0, vy: 100 };
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 },
    { x: 120, y: 60, w: 40, h: 20, alive: true, points: 10 },
  ];
  // In a real game, the ball might overlap two bricks at the same time.
  // We want to make sure the bounce is only applied once.
  frame(mockCtx, state);
  // If it bounced twice, vy would be positive again.
  assert.ok(state.ball.vy < 0, 'ball should only bounce once even if overlapping multiple bricks');
});

test('brick collision: tunnelling', () => {
  const state = createState(1);
  // Ball is moving very fast, skipping over the brick in one step.
  // For this test to work, we need to simulate the movement within the collision check.
  // Since we are currently calling frame(), we need to make sure the tunnelling fix
  // considers the previous position.
  state.ball = { x: 100, y: 50, r: 7, vx: 0, vy: 1000 }; 
  state.ball.prevY = 40; // hypothetical previous position
  state.bricks = [
    { x: 80, y: 60, w: 40, h: 20, alive: true, points: 10 }
  ];
  frame(mockCtx, state);
  assert.ok(state.ball.vy < 0, 'ball should not tunnel through the brick');
});

