export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;
  let hasBounced = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    // Bounding box of the move
    const minX = Math.min(ball.prevX, ball.x) - ball.r;
    const maxX = Math.max(ball.prevX, ball.x) + ball.r;
    const minY = Math.min(ball.prevY, ball.y) - ball.r;
    const maxY = Math.max(ball.prevY, ball.y) + ball.r;

    if (maxX < brick.x || minX > brick.x + brick.w || maxY < brick.y || minY > brick.y + brick.h) {
      continue;
    }

    // Check for discrete collision or tunnelling
    const isColliding = collides(ball, brick);
    const isTunnelling = !isColliding && (
      (ball.prevX <= brick.x + brick.w && ball.x >= brick.x) &&
      (ball.prevY <= brick.y && ball.y >= brick.y) || // tunnel through top
      (ball.prevY >= brick.y + brick.h && ball.y <= brick.y + brick.h) // tunnel through bottom
      // This is still a bit simplified.
    );

    // A better way to detect tunnelling: if it's not colliding now, but the 
    // movement box intersects, and the ball has crossed the brick's boundaries.
    const crossedY = (ball.prevY - ball.r <= brick.y && ball.y + ball.r >= brick.y) ||
                     (ball.prevY + ball.r >= brick.y + brick.h && ball.y - ball.r <= brick.y + brick.h);
    const crossedX = (ball.prevX - ball.r <= brick.x && ball.x + ball.r >= brick.x) ||
                     (ball.prevX + ball.r >= brick.x + brick.w && ball.x - ball.r <= brick.x + brick.w);

    if (isColliding || (crossedX && crossedY)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      // To resolve the bounce, we need to know which face was hit.
      // If tunnelling, we approximate the hit face based on the movement vector.
      let px, py;
      if (isColliding) {
        const dx1 = ball.x + ball.r - brick.x;
        const dx2 = brick.x + brick.w - (ball.x - ball.r);
        const dy1 = ball.y + ball.r - brick.y;
        const dy2 = brick.y + brick.h - (ball.y - ball.r);
        px = Math.min(dx1, dx2);
        py = Math.min(dy1, dy2);
      } else {
        // Tunnelling: assume hit based on velocity direction
        // This is a simplification.
        px = Math.abs(ball.vx) < Math.abs(ball.vy) ? 0 : 100;
        py = Math.abs(ball.vx) < Math.abs(ball.vy) ? 100 : 0;
      }

      if (px < py) {
        // Side hit
        if (!hasBounced) ball.vx *= -1;
        ball.x = (ball.vx < 0) ? brick.x + brick.w + ball.r : brick.x - ball.r;
      } else if (py < px) {
        // Top/Bottom hit
        if (!hasBounced) ball.vy *= -1;
        ball.y = (ball.vy < 0) ? brick.y + brick.h + ball.r : brick.y - ball.r;
      } else {
        // Corner hit
        if (!hasBounced) {
          ball.vx *= -1;
          ball.vy *= -1;
        }
        ball.x = (ball.vx < 0) ? brick.x + brick.w + ball.r : brick.x - ball.r;
        ball.y = (ball.vy < 0) ? brick.y + brick.h + ball.r : brick.y - ball.r;
      }
      hasBounced = true;
    }
  }
}

